//! Decoding over the generated tables, and printing an instruction the way GNU objdump does.
//!
//! `op`, `esp32` and `esp32s3` are generated by `gen/generate.py` from the two
//! `xtensa-modules.c` files, and `gen/regen.sh` writes them. `Op` is the union of both opcode
//! tables. Each chip's decoder names only that chip's ops, which the generator asserts.

#[rustfmt::skip]
mod esp32;
#[rustfmt::skip]
mod esp32s3;
#[rustfmt::skip]
mod op;

pub use op::Op;

use op::SlotResult;

impl Op {
    /// The mnemonic GNU objdump prints.
    pub fn name(self) -> &'static str {
        op::OP_NAME[self as usize]
    }
}

/// One decoded instruction. `fields` holds the visible operands in the order objdump prints
/// them, after the table's decoding: a register is its number, an immediate is its value, and a
/// PC-relative operand is its target address.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct Insn {
    pub op: Op,
    pub len: u8,
    pub fields: [u32; 8],
    pub field_count: u8,
}

#[derive(Clone, Debug, PartialEq, Eq)]
pub enum Decoded {
    Insn(Insn),
    /// The first byte starts no format, or the slice is shorter than the format.
    Byte(u8),
    /// The format's slot accepts no opcode.
    Undefined(u8),
}

impl Decoded {
    pub fn size(&self) -> u8 {
        match self {
            Decoded::Byte(_) | Decoded::Undefined(_) => 1,
            Decoded::Insn(insn) => insn.len,
        }
    }
}

macro_rules! decoder {
    ($name:ident, $m:ident) => {
        pub(crate) mod $name {
            use super::{Decoded, Insn, SlotResult, byte_operand, format_operand, op, $m};

            /// The instruction length the first byte names, or `None` when it starts no format.
            pub(crate) fn len(first: u8) -> Option<u8> {
                $m::format_len(first).map(|(len, _)| len)
            }

            /// Decodes the instruction at the front of `bytes`, whose first byte is at `pc`.
            ///
            /// A null field getter keeps the previous operand's decoded value. GNU does that for
            /// the 16-bit encodings that fall through to `lsi`, where `FIELD_imm8` has no getter
            /// and the printed offset is the address register shifted left by two.
            pub(crate) fn decode(bytes: &[u8], pc: u32) -> Option<Decoded> {
                let first = *bytes.first()?;
                let Some((len, slot)) = $m::format_len(first) else {
                    return Some(Decoded::Byte(first));
                };
                if bytes.len() < len as usize {
                    return Some(Decoded::Byte(first));
                }
                let mut word = 0u32;
                for (i, byte) in bytes.iter().take(len as usize).enumerate() {
                    word |= u32::from(*byte) << (8 * i as u32);
                }
                // Field getters and the opcode test read the slot buffer. On format_32 that
                // buffer is a permutation of the instruction word.
                let word = $m::extract_slot(slot, word);
                let op = match $m::decode_slot(slot, word) {
                    SlotResult::Undefined => return Some(Decoded::Undefined(first)),
                    SlotResult::Op(op) => op,
                };
                let getters = $m::FIELD[slot as usize];
                let mut val = 0u32;
                let mut fields = [0u32; 8];
                let mut count = 0usize;
                for arg in $m::ICLASS_OPS[$m::OP_CLASS[op as usize] as usize] {
                    let operand = &$m::OPERANDS[arg.operand as usize];
                    let raw = match getters[operand.field as usize] {
                        Some(get) => get(word),
                        None => val,
                    };
                    val = (operand.rtoa)((operand.sem)(raw), pc);
                    if operand.visible && arg.show {
                        fields[count] = val;
                        count += 1;
                    }
                }
                Some(Decoded::Insn(Insn {
                    op,
                    len,
                    fields,
                    field_count: count as u8,
                }))
            }

            pub(crate) fn render(decoded: &Decoded) -> String {
                let insn = match decoded {
                    Decoded::Byte(byte) | Decoded::Undefined(byte) => {
                        return format!(".byte\t{}", byte_operand(*byte));
                    }
                    Decoded::Insn(insn) => insn,
                };
                let name = op::OP_NAME[insn.op as usize];
                let class = $m::OP_CLASS[insn.op as usize] as usize;
                let mut parts = Vec::new();
                let mut seen = 0usize;
                for arg in $m::ICLASS_OPS[class] {
                    let operand = &$m::OPERANDS[arg.operand as usize];
                    if !operand.visible || !arg.show {
                        continue;
                    }
                    parts.push(format_operand(
                        operand.prefix,
                        operand.width,
                        operand.pcrel,
                        insn.fields[seen],
                    ));
                    seen += 1;
                }
                if parts.is_empty() {
                    name.to_string()
                } else {
                    format!("{name}\t{}", parts.join(", "))
                }
            }
        }
    };
}

decoder!(classic, esp32);
decoder!(s3, esp32s3);

/// GNU prints the byte with `%#02x`. Zero has no `0x` prefix, so it is `00`.
fn byte_operand(byte: u8) -> String {
    if byte == 0 {
        "00".to_string()
    } else {
        format!("0x{byte:x}")
    }
}

fn format_operand(prefix: u8, width: u8, pcrel: bool, value: u32) -> String {
    if prefix != 0 {
        if width > 1 {
            let mark = prefix as char;
            return (0..width)
                .map(|step| format!("{mark}{}", value + u32::from(step)))
                .collect::<Vec<_>>()
                .join(":");
        }
        return format!("{}{value}", prefix as char);
    }
    if pcrel {
        return format!("0x{value:x}");
    }
    let signed = value as i32;
    if (-255..=255).contains(&signed) {
        format!("{signed}")
    } else {
        format!("0x{value:x}")
    }
}
